354:                     return 'Invalid email';
355:                   }
356:                   return null;
357:                 },
358:               ),
359:               ElevatedButton(
360:                 key: const Key('submit'),
361:                 onPressed: () => formKey.currentState!.validate(),
362:                 child: const Text('Submit'),
363:               ),
364:             ],
365:           ),
366:         ),
367:       ),
368:     ),
369:   );
370:   
371:   // Enter invalid email
372:   await tester.enterText(find.byKey(const Key('email')), 'invalid');
373:   await tester.tap(find.byKey(const Key('submit')));
374:   await tester.pump();
375:   
376:   // Should show error
377:   expect(find.text('Invalid email'), findsOneWidget);
378:   
379:   // Enter valid email
380:   await tester.enterText(find.byKey(const Key('email')), 'test@example.com');
381:   await tester.tap(find.byKey(const Key('submit')));
382:   await tester.pump();
383:   
384:   // Should hide error
385:   expect(find.text('Invalid email'), findsNothing);
386: });
387: ```
388: 
389: ### Multiple Form Fields
390: 
391: ```dart
392: testWidgets('form with multiple fields', (tester) async {
393:   await tester.pumpWidget(
394:     MaterialApp(
395:       home: Scaffold(
396:         body: Form(
397:           child: Column(
398:             children: [
399:               TextFormField(
400:                 key: const Key('name'),

400:                 key: const Key('name'),
401:                 decoration: const InputDecoration(labelText: 'Name'),
402:               ),
403:               TextFormField(
404:                 key: const Key('email'),
405:                 decoration: const InputDecoration(labelText: 'Email'),
406:               ),
407:               ElevatedButton(
408:                 key: const Key('submit'),
409:                 onPressed: () {},
410:                 child: const Text('Submit'),
411:               ),
412:             ],
413:           ),
414:         ),
415:       ),
416:     ),
417:   );
418:   
419:   // Fill form
420:   await tester.enterText(find.byKey(const Key('name')), 'John Doe');
421:   await tester.enterText(find.byKey(const Key('email')), 'john@example.com');
422:   
423:   // Submit
424:   await tester.tap(find.byKey(const Key('submit')));
425:   await tester.pumpAndSettle();
426: });
427: ```
428: 
429: ## Testing Animations
430: 
431: ```dart
432: testWidgets('animation plays correctly', (tester) async {
433:   await tester.pumpWidget(const AnimatedWidget());
434:   
435:   // Initial state
436:   expect(find.byType(Opacity), findsOneWidget);
437:   
438:   // Trigger animation
439:   await tester.tap(find.byType(ElevatedButton));
440:   
441:   // Pump animation frames
442:   await tester.pump();
443:   await tester.pump(const Duration(milliseconds: 100));
444:   await tester.pump(const Duration(milliseconds: 100));
445:   
446:   // Animation complete
447:   await tester.pumpAndSettle();
448:   
449:   // Verify final state
450:   final opacity = tester.widget<Opacity>(find.byType(Opacity));
451:   expect(opacity.opacity, 0.0);
452: });
453: ```
454: 
455: ## Testing Custom Widgets
456: 
457: ### Testing InheritedWidgets
458: 
459: ```dart
460: class MyInheritedWidget extends InheritedWidget {
461:   final String data;
462:   
463:   const MyInheritedWidget({
464:     super.key,
465:     required this.data,
466:     required Widget child,
467:   }) : super(child: child);
468:   
469:   static MyInheritedWidget of(BuildContext context) {
470:     return context.dependOnInheritedWidgetOfExactType<MyInheritedWidget>()!;
471:   }
472:   
473:   @override
474:   bool updateShouldNotify(MyInheritedWidget oldWidget) =>
475:       data != oldWidget.data;
476: }
477: 
478: testWidgets('inherited widget provides data', (tester) async {
479:   await tester.pumpWidget(
480:     MyInheritedWidget(
481:       data: 'Test Data',
482:       child: Builder(
483:         builder: (context) {
484:           return Text(MyInheritedWidget.of(context).data);
485:         },
486:       ),
487:     ),
488:   );
489:   
490:   expect(find.text('Test Data'), findsOneWidget);
491: });
492: ```
493: 
494: ### Testing StatefulWidget
495: 
496: ```dart
497: class CounterWidget extends StatefulWidget {
498:   @override
499:   State<CounterWidget> createState() => _CounterWidgetState();
500: }
501: 
502: class _CounterWidgetState extends State<CounterWidget> {
503:   int _count = 0;
504:   
505:   void _increment() => setState(() => _count++);
506:   
507:   @override
508:   Widget build(BuildContext context) {
509:     return Column(
510:       children: [
511:         Text('Count: $_count'),
512:         ElevatedButton(
513:           key: const Key('increment'),
514:           onPressed: _increment,
515:           child: const Text('Increment'),
516:         ),
517:       ],
518:     );
519:   }
520: }
521: 
522: testWidgets('CounterWidget increments correctly', (tester) async {
523:   await tester.pumpWidget(
524:     MaterialApp(
525:       home: Scaffold(
526:         body: CounterWidget(),
527:       ),
528:     ),
529:   );
530:   
531:   // Initial count
532:   expect(find.text('Count: 0'), findsOneWidget);
533:   
534:   // Increment
535:   await tester.tap(find.byKey(const Key('increment')));
536:   await tester.pump();
537:   
538:   expect(find.text('Count: 1'), findsOneWidget);
539: });
540: ```
541: 
542: ## Testing with Mock Data
543: 
544: ```dart
545: class ProductList extends StatelessWidget {
546:   final List<Product> products;
547:   
548:   const ProductList({super.key, required this.products});
549:   
550:   @override
551:   Widget build(BuildContext context) {
552:     return ListView.builder(
553:       itemCount: products.length,
554:       itemBuilder: (context, index) => ListTile(
555:         title: Text(products[index].name),
556:         subtitle: Text('\$${products[index].price}'),
557:       ),
558:     );
559:   }
560: }

560: }
561: 
562: testWidgets('displays list of products', (tester) async {
563:   final products = [
564:     Product(name: 'Product 1', price: 10.99),
565:     Product(name: 'Product 2', price: 20.99),
566:   ];
567:   
568:   await tester.pumpWidget(
569:     MaterialApp(
570:       home: Scaffold(
571:         body: ProductList(products: products),
572:       ),
573:     ),
574:   );
575:   
576:   expect(find.text('Product 1'), findsOneWidget);
577:   expect(find.text('\$10.99'), findsOneWidget);
578:   expect(find.text('Product 2'), findsOneWidget);
579:   expect(find.text('\$20.99'), findsOneWidget);
580: });
581: ```
582: 
583: ## Testing Accessibility
584: 
585: ```dart
586: testWidgets('widget has proper semantics', (tester) async {
587:   await tester.pumpWidget(
588:     MaterialApp(
589:       home: Semantics(
590:         label: 'Submit button',
591:         button: true,
592:         child: ElevatedButton(
593:           onPressed: () {},
594:           child: const Text('Submit'),
595:         ),
596:       ),
597:     ),
598:   );
599:   
600:   final semantics = tester.getSemantics(find.byType(ElevatedButton));
601:   expect(semantics.label, 'Submit button');
602:   expect(semantics.hasAction(SemanticsAction.tap), true);
603: });
604: ```
605: 
606: ## Best Practices
607: 
608: 1. **Use descriptive test names** - Explain what and why
609: 2. **Keep tests independent** - Each test should be standalone
610: 3. **Use pumpAndSettle()** - Wait for all animations
611: 4. **Test user behavior, not implementation** - Focus on what users see and do
612: 5. **Group related tests** - Use `group()` for organization
613: 6. **Test edge cases** - Empty lists, null values, errors
614: 7. **Use keys for widgets** - Makes finding easier and more reliable
615: 8. **Test accessibility** - Verify semantic labels and actions
616: 
617: ## Common Patterns
618: 
619: ### Testing Navigation
620: 
621: ```dart
622: testWidgets('navigates to detail screen', (tester) async {
623:   await tester.pumpWidget(
624:     MaterialApp(
625:       initialRoute: '/',
626:       routes: {
627:         '/': (context) => const HomeScreen(),
628:         '/detail': (context) => const DetailScreen(),
629:       },
630:     ),
631:   );
632:   
633:   // Tap navigation button
634:   await tester.tap(find.text('Go to Detail'));
635:   await tester.pumpAndSettle();
636:   
637:   // Verify navigation
638:   expect(find.text('Detail Screen'), findsOneWidget);
639:   expect(find.text('Home Screen'), findsNothing);
640: });
641: ```
642: 
643: ### Testing Loading States
644: 
645: ```dart
646: testWidgets('shows loading then content', (tester) async {
647:   bool isLoading = true;
648:   
649:   await tester.pumpWidget(
650:     MaterialApp(
651:       home: StatefulBuilder(
652:         builder: (context, setState) {
653:           return isLoading
654:               ? const CircularProgressIndicator()
655:               : const Text('Content Loaded');
656:         },
657:       ),
658:     ),
659:   );
660:   
661:   expect(find.byType(CircularProgressIndicator), findsOneWidget);
662:   
663:   // Simulate data load
664:   isLoading = false;
665:   await tester.pump();
666:   
667:   expect(find.byType(CircularProgressIndicator), findsNothing);
668:   expect(find.text('Content Loaded'), findsOneWidget);
669: });
670: ```

